export function reorderPlacement(peers, id, direction) {
  const index = peers.findIndex(item => item.id === id);
  if (index < 0) return null;
  if (direction === 'first' && index > 0) return { beforeId: peers[0].id };
  if (direction === 'up' && index > 0) return { beforeId: peers[index - 1].id };
  if (direction === 'down' && index < peers.length - 1) return index + 2 < peers.length ? { beforeId: peers[index + 2].id } : { beforeId: null };
  if (direction === 'last' && index < peers.length - 1) return { beforeId: null };
  return null;
}

export function menuNextIndex(key, index, count) {
  if (!count) return -1;
  if (key === 'Home') return 0;
  if (key === 'End') return count - 1;
  if (key === 'ArrowDown') return (index + 1 + count) % count;
  if (key === 'ArrowUp') return index < 0 ? count - 1 : (index - 1 + count) % count;
  return -1;
}

export const reorderAvailable = state => Boolean(state?.can_edit && state.edit !== 'Saving' && !state.query && state.selected_group_id !== WINDOW_SNAPSHOT_GROUP_ID);

export function reorderDropAction(kind, sourceId, source, target) {
  if (kind === 'group' && target?.beforeId) return { action: 'reorderGroup', args: [sourceId, target.beforeId] };
  if (kind !== 'material' || !target) return null;
  if (source?.group_id === target.groupId && source?.role === target.role && target.beforeId)
    return { action: 'reorderMaterial', args: [sourceId, target.beforeId] };
  return { action: 'moveMaterial', args: [sourceId, target.groupId, target.role, target.beforeId] };
}

const statusText = Object.freeze({ exists:'利用可能', missing:'見つかりません', timeout:'確認タイムアウト', access_denied:'アクセス拒否', unchecked:'未確認', error:'確認エラー', open:'開いています', not_detected:'未起動', unknown:'状態不明', not_trackable:'追跡対象外' });
const droppedFailureText=Object.freeze({not_found:'見つかりません',inaccessible:'アクセスできません',unsupported:'未対応の種類です',duplicate:'同じ資料が重複しています',invalid_path:'パスを確認してください'});
export function renderDroppedFilesDialog(dropped,groups,{text,list,group,confirm}){
  const failures=dropped.failures??[];
  text.textContent=failures.length?`${dropped.candidates.length}件を登録できます。${failures.length}件は登録できませんでした。`:`${dropped.candidates.length}件の資料を登録します。`;
  list.replaceChildren();
  for(const candidate of dropped.candidates){const item=list.ownerDocument.createElement('li');item.textContent=`${candidate.target_type==='folder'?'フォルダー':'ファイル'}: ${candidate.name}`;list.append(item)}
  for(const failure of failures){const item=list.ownerDocument.createElement('li');item.className='dnd-failure';item.textContent=`登録不可: ${failure.path} — ${droppedFailureText[failure.reason]??'確認できませんでした'}`;list.append(item)}
  group.replaceChildren();
  for(const value of groups){const option=group.ownerDocument.createElement('option');option.textContent=value.name;option.value=value.id;group.append(option)}
  group.value=dropped.group_id;
  confirm.disabled=!dropped.candidates.length;
}
